"""Writes tests/m4/07-view-churn.txt: views of resources made, released and
made again in a fixed random order (the table of views' entries freed and
reused under new generations, its index growing and closing up), every slot
dumped as it goes, so the port's index is checked against the reference's
log for log.

Usage: python -I tools/gen_view_churn.py <out.txt> [seed]
"""
import random
import sys

out = sys.argv[1]
rng = random.Random(int(sys.argv[2]) if len(sys.argv) > 2 else 7)
lines = [
    '# M4.5: the table of views under churn (generated by tools/gen_view_churn.py;',
    '# do not edit): views of resources made, released and made again; samplers',
    '# and views of placed memory between them; every slot dumped.',
    'runtime',
    'create_device dev device11',
    'desc_heap dev cpu 0 512',
    'desc_heap dev smp 1 64',
]
alive = {}
made = 0
for step in range(600):
    r = rng.random()
    if r < 0.15 or not alive:
        name = f'r{made}'
        made += 1
        if rng.random() < 0.5:
            lines.append(f'committed dev {name} 1 B{rng.choice([4096, 65536, 200000])}')
        else:
            lines.append(f'committed dev {name} 1 T3/{rng.choice([64, 128, 256])}x{rng.choice([64, 128])}/f28')
        alive[name] = True
    elif r < 0.25:
        name = rng.choice(sorted(alive))
        lines.append(f'release {name}')
        del alive[name]
    elif r < 0.75:
        name = rng.choice(sorted(alive))
        slot = rng.randrange(512)
        k = rng.random()
        desc = '' if rng.random() < 0.4 else ' w:' + ','.join(str(rng.choice([0, 1, 2, 28, 4, 5768])) for _ in range(rng.randrange(1, 6)))
        if k < 0.5:
            lines.append(f'srv dev cpu:{slot} {name}{desc}')
        else:
            counter = rng.choice(sorted(alive) + ['null', 'null'])
            lines.append(f'uav dev cpu:{slot} {name} {counter}{desc}')
        lines.append(f'slot cpu:{slot}')
    elif r < 0.85:
        slot = rng.randrange(64)
        words = ','.join(str(rng.choice([0, 1, 2, 3, 16])) for _ in range(rng.randrange(1, 13)))
        lines.append(f'sampler dev smp:{slot} w:{words}')
        lines.append(f'slot smp:{slot}')
    elif r < 0.95:
        slot = rng.randrange(512)
        lines.append(f'slot cpu:{slot}')
    else:
        a, b = rng.randrange(400), rng.randrange(400)
        n = rng.randrange(1, 8)
        lines.append(f'desc_copy1 dev {n} cpu:{a} cpu:{b} 0')
        lines.append(f'slot cpu:{a}')
lines.append('end')
open(out, 'w', encoding='utf-8', newline='\n').write('\n'.join(lines) + '\n')
print(f'{out}: {len(lines)} lines')
